<template>
  <div class="searchMoreInfo">
    <title-line :title="title" />
    <van-tabs v-model="currentIndex" :ellipsis="false" @change="getSubClass">
      <van-tab v-for="item in typeList" :key="item.value" :title="item.label">
        <div class="container">
          <div class="search">
            <van-search
              v-model="searchText"
              :placeholder="$t('hxhash.hx56')"
              left-icon=""
              @search="onSearch()"
            >
              <template #right-icon>
                <div @click="onSearch"><van-icon name="search" color="#87b7ff" size="24" /></div>
              </template>
            </van-search>
          </div>
          <div class="verify-text" @click="$router.push({path:'/showPdf1'})"><div class="text">{{ $t('hxhash.hx57') }}</div><van-icon style="margin-left:8px" name="question-o" /></div>
          <div class="detailList">
            <van-pull-refresh v-model="refreshing" :loading-text="$t('tzjl.tzjl50')" :pulling-text="$t('tzjl.tzjl51')" :loosing-text="$t('tzjl.tzjl52')" :finished-text="$t('tzjl.tzjl53')" @refresh="onRefresh">
              <van-list
                v-model="loading"
                :finished="finished"
                :loading-text="$t('tzjl.tzjl50')"
                finished-text=""
                @load="onLoad"
              >
                <is-empty v-if="recordList.length===0" />
                <div v-for="(item,index) in recordList" :key="index" class="list-box">
                  <div v-for="(ele,j) in item" :key="j" class="detail">
                    <span class="detailLabel">{{ ele.label }}</span>
                    <div v-if="ele.label===$t('hxhash.hx58')" class="openTime">
                      <span class="detailValue">{{ ele.showValue }}</span>
                    </div>
                    <div v-else-if="ele.label===$t('hxhash.hx36')" class="Period">
                      <span class="detailValue" @click="doCopy(ele.value)">{{ ele.showValue }}</span>
                    </div>
                    <div v-else class="Period">
                      <span class="detailValue" @click="doCopy(ele.value)">{{ ele.value }}</span>
                    </div>
                  </div>
                </div>
              </van-list>
            </van-pull-refresh>
          </div>
          <div class="tips">
            <div class="warning_icon" />
            {{ $t('hxhash.hx63') }}</div>
        </div>
      </van-tab>
    </van-tabs>
  </div>
</template>
<script>
import TitleLine from '../modules/TitleLine'
import { searchKey, searchKey1 } from '@/api/game'
export default {
  components: {
    TitleLine
  },
  props: {
    currentValue: {
      type: Number,
      default: 0
    }
  },
  data() {
    return {
      title: this.$t('hxhash.hx54'),
      typeList: [{ label: this.$t('hxhash.hx55'), value: 0 }, { label: this.$t('hxhash.hx62'), value: 1 }
      ],
      recordList: [
      ],
      currentIndex: this.currentValue,
      loading: false,
      finished: false,
      refreshing: false,
      pageNum: 1,
      pageSize: 10,
      searchText: ''
    }
  },
  methods: {
    onSearch() {
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      // this.loading = true
      const param = {
        suid: this.$store.getters.token,
        block: '',
        blockurl: '',
        blocktime: '',
        pages: 1,
        keyword: this.searchText
      }
      this.onLoad(param)
    },
    onLoad(data) {
      if (this.currentIndex === 0) {
        searchKey(data).then(res => {
          this.totalData = res.totalData
          // this.recordList = res.recordList
          if (this.refreshing) {
            this.recordList = []
            this.refreshing = false
          }
          this.recordList = this.recordList.concat(res.recordList)
          this.loading = false
          this.pageNum++
          if (this.recordList.length >= Number(res.allnums)) {
            this.finished = true
          }
        })
      } else {
        searchKey1(data).then(res => {
          this.totalData = res.totalData
          // this.recordList = res.recordList
          if (this.refreshing) {
            this.recordList = []
            this.refreshing = false
          }
          this.recordList = this.recordList.concat(res.recordList)
          this.loading = false
          this.pageNum++
          if (this.recordList.length >= Number(res.allnums)) {
            this.finished = true
          }
        })
      }
    },
    onRefresh() {
      // 清空列表数据
      this.finished = false
      this.pageNum = 1
      this.refreshing = true
      // 重新加载数据
      // 将 loading 设置为 true，表示处于加载状态
      this.loading = true
      this.onLoad()
    },
    getSubClass(value, label) {
      this.onRefresh()
      this.currentIndex = value
    },
    doCopy(val) {
      this.$copyText(val).then(
        (e) => {
          // success
          this.$toast.success(this.$t('yqhy.yqhy10'))
        },
        (e) => {
          // fail
          console.log(e)
        }
      )
    }
  }

}
</script>
<style lang="less">
.searchMoreInfo {
    min-height: 100vh;
    width: 100%;
    background: #19223b;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .container{
      padding: 0 20px;
      .search{
          margin-top: 20px;
          background: rgba(0,0,0,.16);
          // height: 86px;
          border-radius: 12px;
      }
      .verify-text{
          .text{
          color: transparent;
          background-image: linear-gradient(45deg, #f5cc96, #fcf1c6);
          -webkit-background-clip: text;
          background-clip: text;
          font-style:italic;
          padding: 0 10px;
          }
          margin-top: 20px;
          font-size: 32px;
          display: flex;
          justify-content: flex-end;
          // float: right;

      }
      .detailList {
            margin-top: 20px;
            height: 860px;
            overflow: hidden auto;
            .list-box {
                background: #202a41;
                border-radius: 26px;
                padding: 30px 32px 28px;
                margin-bottom: 24px;
                .detail {
                    display: flex;
                    justify-content: space-between;
                    align-items: center;
                    height: 68px;
                    padding: 0 5px;
                    // border-bottom: 1px solid #293652;
                    border-bottom-color: #293652;
                    border-bottom-style: solid;
                    border-bottom-width: 2px;
                    .detailLabel {
                        font-size: 24px;
                        color: #7987a7;
                        // width: 400px;
                    }
                    .openTime{
                      .detailValue{
                        color: #fff;
                      }
                    }

                    .Period {
                        display: flex;
                        align-items: center;
                        width: 480px;
                        text-align: right;
                        .detailValue{
                          width: 480px;
                          font-size: 24px;
                          color: #7987a7;
                        }
                        .copy-icon{
                            margin: 0 20px;
                            width: 36px;
                            height: 36px;
                            background: url('~@/assets/portal/btn_fuzhi.png') no-repeat 50%;
                            background-size: 100% 100%;
                        }
                        .verify {
                            max-width: 140px;
                            min-width: 120px;
                            min-height: 50px;
                            padding: 0 6px;
                            display: flex;
                            justify-content: center;
                            align-items: center;
                            text-align: center;
                            line-height: 26px;
                            background: hsla(0,0%,100%,.05);
                            border-radius: 8px;
                        }
                    }
                }
            }
      }
      .tips{
        display: flex;
        font-size: 24px;
        font-weight: 400;
        color: rgb(186,155,98);
        margin: 20px 0;
        .warning_icon{
          width: 20px;
          height: 20px;
          margin-right: 12px;
          background-image: url('~@/assets/portal/warning_icon.png');
          background-position: 0% 0%;
          background-size: 100% 100%;
          background-repeat: no-repeat;
        }
      }
    }
    .van-search{
        padding: 0;
        border-radius:10px;
        background-color: transparent;
    }
    .van-search__content{
        background-color: transparent;
        border-radius:10px;
    }
    .van-field__control{
      height: 48px;
      color: #fff;
    }
    .van-field__control::placeholder{
        color: #7582a2;
    }
    .van-tabs__nav{
        background: none;
    }
    .van-tab--active {
        color: #fff !important;
    }
    .van-tab{
        color:#7582a2;
        width: 156px;
        font-size: 24px;
        font-weight: 600;
        padding: 0;
    }
    .van-tabs__line {
        background-color: #87b7ff;
        width: 156px;
        height: 2px;
    }
}
</style>
